package com.travel.food;
import com.travel.auth.*; import com.travel.place.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/foods") public class FoodController {final FoodRepository foods;final UserRepository users;final PlaceRepository places; public FoodController(FoodRepository f,UserRepository u,PlaceRepository p){foods=f;users=u;places=p;} public record Input(@NotBlank String name,@NotBlank String address,@NotNull Double longitude,@NotNull Double latitude,Double price,@DecimalMin("0") @DecimalMax("5") Double rating,String openingHours,String link,String notes,@Pattern(regexp="draft|published|archived") String status,Long placeId){} private UserAccount user(AccountPrincipal p){return users.findById(p.id()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"请重新登录"));} private Food own(Long id,AccountPrincipal p){return foods.findByIdAndUserId(id,p.id()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"美食不存在"));} @GetMapping public List<FoodView> list(@AuthenticationPrincipal AccountPrincipal p){return foods.findByUserIdAndStatusOrderByIdDesc(p.id(),"published").stream().map(FoodView::from).toList();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public FoodView create(@AuthenticationPrincipal AccountPrincipal p,@Valid @RequestBody Input i){return FoodView.from(foods.save(apply(new Food(user(p)),i,p)));} @GetMapping("/{id}") public FoodView get(@PathVariable Long id,@AuthenticationPrincipal AccountPrincipal p){return FoodView.from(own(id,p));} @PutMapping("/{id}") public FoodView update(@PathVariable Long id,@AuthenticationPrincipal AccountPrincipal p,@Valid @RequestBody Input i){return FoodView.from(foods.save(apply(own(id,p),i,p)));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal AccountPrincipal p){foods.delete(own(id,p));} private Food apply(Food f,Input i,AccountPrincipal p){f.name=i.name();f.address=i.address();f.longitude=i.longitude();f.latitude=i.latitude();f.price=i.price();f.rating=i.rating();f.openingHours=i.openingHours();f.link=i.link();f.notes=i.notes();f.status=i.status()==null?"draft":i.status();f.place=i.placeId()==null?null:places.findByIdAndUserId(i.placeId(),p.id()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"关联景点不存在"));return f;}}
